decks.styleCss:
@import url('https://fonts.googleapis.com/css2?family=Fira+Code:wght@300;400;500;600;700&family=JetBrains+Mono:wght@300;400;500;600;700&display=swap');
:root {
  --bg: #0d1117;
  --slide-hero-bg: #0d1117;
  --slide-hero-rgb: 13,17,23;
  --text: #39ff14;
  --text-muted: rgba(255,255,255,.55);
  --bg-card: rgba(255,255,255,.05);
  --bg-card-hover: rgba(255,255,255,.09);
  --border: rgba(255,255,255,.10);
  --border-hover: rgba(255,255,255,.28);
  --nav-bg: rgba(0,0,0,.65);
  --nav-border: rgba(255,255,255,.08);
  --dot-inactive: rgba(255,255,255,.18);
  --counter: #555;
}
body { font-family: 'Fira Code', 'JetBrains Mono', monospace; }
